const factors = $('Obtener rating_factors del producto').item.json.rating_factors || [];
const trigger = $('Entrada (tool)').item.json;
let inputs = {};
try { inputs = JSON.parse(trigger.inputs_json || '{}'); } catch (e) { inputs = {}; }

const missing = factors.filter(f => inputs[f] === undefined || inputs[f] === null || inputs[f] === '');

return [{
  json: {
    ok: missing.length === 0,
    missing_fields: missing,
    inputs,
    contact_chat_id: trigger.contact_chat_id,
    product_code: trigger.product_code
  }
}];

// La tarifa oficial del RCV (Gaceta 6.835) está en euros anclados al TCR del BCV:
// hay que convertirla para poder decirle un precio al cliente. Las tarifas
// comerciales de otros ramos ya vienen en su moneda y no se tocan.
function tasas() {
  try {
    const r = $('Tasa BCV (EUR/USD)').first().json || {};
    return { eur: Number(r.EUR) || null, usd: Number(r.USD) || null, fecha: r.effective_date || null };
  } catch (e) {
    return { eur: null, usd: null, fecha: null };
  }
}
function convertir(line, premium) {
  if (premium == null) return { premium: null, currency: null };
  if ((line.currency || '').toUpperCase() !== 'EUR') {
    return { premium, currency: line.currency || null };
  }
  const t = tasas();
  if (!t.eur) {
    // Sin tasa no se inventa un precio: se devuelve en euros y se marca.
    return { premium, currency: 'EUR', rate_missing: true };
  }
  const ves = premium * t.eur;
  return {
    premium: Math.round(ves * 100) / 100,
    currency: 'VES',
    premium_eur: premium,
    premium_usd: t.usd ? Math.round((ves / t.usd) * 100) / 100 : null,
    rate_eur_ves: t.eur,
    rate_date: t.fecha,
  };
}

const line = $json;
const apiOk = line.statusCode && line.statusCode < 400 && line.body?.premium;
if (apiOk) return { json: { ...line, premium: line.body.premium, source: 'api' } };
if (line.base_premium != null) {
  const c = convertir(line, Number(line.base_premium));
  return { json: { ...line, ...c, source: 'estimate' } };
}
return { json: { ...line, premium: null, source: 'unavailable' } };

