const line = $json;
if (line.base_premium != null) {
  const c = convertir(line, Number(line.base_premium));
  return { json: { ...line, ...c, source: line.source || 'manual' } };
}
return { json: { ...line, premium: null, source: 'unavailable' } };

const lines = $input.all().map(i => i.json);
const available = lines.filter(l => l.premium != null);
available.sort((a, b) => a.premium - b.premium);
available.forEach((l, idx) => { l.rank = idx + 1; });
lines.forEach(l => {
  if (l.premium != null) {
    l.commission_amount = Math.round((l.premium * (l.commission_pct || 0) / 100) * 100) / 100;
  } else {
    l.commission_amount = null;
    l.rank = null;
    l.unavailable_reason = l.source === 'unavailable' ? 'sin_tarifa_vigente' : null;
  }
});
return lines.map(l => ({ json: l }));

